from __future__ import annotations
import csv
import io
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse
from .config import settings
from .db import Database

HTML = r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>dexmeme · 1USD Bot</title><style>body{margin:0;background:#0b1020;color:#edf2ff;font-family:system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:28px 18px}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:15px}.actions{display:flex;gap:10px;align-items:center}.button{background:#11182b;border:1px solid #26304a;border-radius:10px;color:#edf2ff;padding:10px 14px;text-decoration:none;font-weight:650;font-size:13px}.muted{color:#8f9bb5}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:22px 0}.card,.panel{background:#11182b;border:1px solid #26304a;border-radius:16px}.card{padding:18px}.label{font-size:12px;color:#8f9bb5;text-transform:uppercase}.value{font-size:28px;font-weight:750;margin-top:7px}.sub{font-size:12px;color:#8f9bb5;margin-top:4px}.panel{overflow:auto;margin:10px 0 20px}.bar{height:12px;background:#1b2642;border-radius:99px;overflow:hidden}.fill{height:100%;background:#7c8cff;width:0}.table{width:100%;border-collapse:collapse;min-width:760px}.table th,.table td{padding:12px 14px;text-align:left;border-bottom:1px solid #26304a;font-size:13px}.table th{color:#8f9bb5}.good{color:#55d187}.bad{color:#ff6b7a}.empty{text-align:center;padding:28px;color:#8f9bb5}@media(max-width:850px){.grid{grid-template-columns:repeat(2,1fr)}.top{display:block}.actions{margin-top:12px}}@media(max-width:520px){.grid{grid-template-columns:1fr}.top{display:block}}</style></head><body><main><div class="top"><div><h1>dexmeme · 1USD Bot</h1><p class="muted">Paper trading · $1 net target · $10 position size · 100+ trades/day research goal</p></div><div class="actions"><a class="button" href="/api/trades.csv" download>Export all trades CSV</a><div class="muted" id="status">LIVE</div></div></div><div class="grid" id="cards"></div><h2>Daily progress</h2><div class="panel" style="padding:16px"><div style="display:flex;justify-content:space-between"><span id="goal">0 / 100 trades</span><span class="muted" id="today">$0.00 today</span></div><div class="bar" style="margin-top:10px"><div class="fill" id="fill"></div></div></div><h2>Open positions</h2><div class="panel" id="positions"></div><h2>Recent closed trades</h2><div class="panel" id="trades"></div><p class="muted" style="text-align:center">Paper mode only · USD is the canonical P&amp;L unit · refreshes every 3 seconds</p></main><script>const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const n=x=>Number(x||0);const money=x=>'$'+n(x).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:4});const pct=x=>(n(x)>=0?'+':'')+n(x).toFixed(3)+'%';const dt=x=>x?new Date(Number(x)*1000).toLocaleString(): '—';function render(s){const cards=[['Trades today',`${s.trades_today}/${s.daily_trade_goal}`,'daily goal'],['Target / trade',money(s.target_net_usd),'net after modeled costs'],['Today P&L',money(s.pnl_today_usd),'closed trades today'],['Total trades',s.trades_total,'paper trades'],['Win rate',s.win_rate_pct+'%',s.closed_trades+' closed'],['Total P&L',money(s.realized_pnl_usd),'realized paper P&L'],['Wins',s.wins,'closed winners'],['Losses',s.losses,'closed losers']];document.getElementById('cards').innerHTML=cards.map(c=>`<div class="card"><div class="label">${c[0]}</div><div class="value">${esc(c[1])}</div><div class="sub">${esc(c[2])}</div></div>`).join('');document.getElementById('goal').textContent=`${s.trades_today} / ${s.daily_trade_goal} trades`;document.getElementById('today').textContent=money(s.pnl_today_usd)+' today';document.getElementById('fill').style.width=Math.min(100,s.trades_today/s.daily_trade_goal*100)+'%';const ps=s.positions||[];document.getElementById('positions').innerHTML=ps.length?`<table class="table"><tr><th>Token</th><th>Entry time</th><th>Entry</th><th>Target</th><th>Size</th></tr>${ps.map(p=>`<tr><td><b>${esc(p.symbol)}</b><br><span class="muted">${esc(p.token_address)}</span></td><td>${dt(p.entry_time)}</td><td>$${n(p.entry_price).toPrecision(8)}</td><td class="good">+${n(p.target_pct).toFixed(3)}%</td><td>${money(p.size_usd)} <span class="muted">(${n(p.size_sol).toFixed(6)} SOL)</span></td></tr>`).join('')}</table>`:'<div class="empty">No open paper positions.</div>';const ts=s.recent_trades||[];document.getElementById('trades').innerHTML=ts.length?`<table class="table"><tr><th>Token</th><th>Entry time</th><th>Exit time</th><th>Entry → Exit</th><th>P&L</th><th>Reason</th></tr>${ts.map(t=>`<tr><td><b>${esc(t.symbol)}</b></td><td>${dt(t.entry_time)}</td><td>${dt(t.exit_time)}</td><td>$${n(t.entry_price).toPrecision(8)} → $${n(t.exit_price).toPrecision(8)}</td><td class="${n(t.pnl_pct)>=0?'good':'bad'}">${money(t.pnl_usd)} <span class="muted">(${pct(t.pnl_pct)})</span></td><td>${esc(t.exit_reason||'closed')}</td></tr>`).join('')}</table>`:'<div class="empty">No closed trades yet.</div>';document.getElementById('status').textContent='LIVE · updated now'}async function refresh(){try{const r=await fetch('/api/stats',{cache:'no-store'});if(!r.ok)throw Error();render(await r.json())}catch(e){document.getElementById('status').textContent='OFFLINE · retrying'}}refresh();setInterval(refresh,3000);</script></body></html>'''

class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        path=urlparse(self.path).path
        if path=='/health': self._json({'ok':True,'mode':'paper'}); return
        if path=='/api/stats':
            db=Database(settings.db_path)
            try:
                total=int(db.conn.execute('SELECT COUNT(*) FROM positions').fetchone()[0]); closed=int(db.conn.execute("SELECT COUNT(*) FROM positions WHERE status='closed'").fetchone()[0]); opens=int(db.conn.execute("SELECT COUNT(*) FROM positions WHERE status='open'").fetchone()[0]); wins=int(db.conn.execute("SELECT COUNT(*) FROM positions WHERE status='closed' AND pnl_pct>0").fetchone()[0]); losses=closed-wins
                row=db.conn.execute("SELECT COALESCE(SUM(pnl_usd),0),COALESCE(AVG(pnl_pct),0) FROM positions WHERE status='closed'").fetchone(); today=db.conn.execute("SELECT COUNT(*),COALESCE(SUM(pnl_usd),0) FROM positions WHERE status='closed' AND date(exit_time)=date('now')").fetchone(); rows=db.conn.execute("SELECT symbol,entry_price,entry_time,exit_price,exit_time,pnl_pct,pnl_usd,exit_reason FROM positions WHERE status='closed' ORDER BY exit_time DESC LIMIT 15").fetchall()
                body={'mode':'paper','trades_total':total,'closed_trades':closed,'open_positions':opens,'wins':wins,'losses':losses,'win_rate_pct':round(wins/closed*100,2) if closed else 0,'realized_pnl_usd':round(float(row[0]),6),'average_closed_pnl_pct':round(float(row[1]),4),'target_net_usd':settings.target_net_usd,'position_size_usd':settings.position_size_usd,'daily_trade_goal':settings.daily_trade_goal,'trades_today':int(today[0]),'pnl_today_usd':round(float(today[1]),6),'positions':[p.__dict__ for p in db.open_positions()],'recent_trades':[dict(r) for r in rows]}
                self._json(body)
            finally: db.close()
            return
        if path=='/api/trades.csv':
            db=Database(settings.db_path)
            try:
                rows=db.conn.execute("SELECT id,token_address,pair_address,symbol,entry_price,entry_time,size_sol,target_pct,status,exit_price,exit_time,exit_reason,pnl_pct,size_usd,entry_sol_usd,exit_sol_usd,pnl_usd FROM positions ORDER BY entry_time ASC").fetchall()
                out=io.StringIO(); writer=csv.writer(out); writer.writerow(['id','token_address','pair_address','symbol','entry_price','entry_time','size_sol','target_pct','status','exit_price','exit_time','exit_reason','pnl_pct','size_usd','entry_sol_usd','exit_sol_usd','pnl_usd']); writer.writerows([tuple(r) for r in rows]); body=out.getvalue().encode('utf-8')
            finally: db.close()
            self.send_response(200); self.send_header('Content-Type','text/csv; charset=utf-8'); self.send_header('Content-Disposition','attachment; filename="dexmeme-1usd-trades.csv"'); self.send_header('Cache-Control','no-store'); self.end_headers(); self.wfile.write(body); return
        if path=='/': self._html(HTML); return
        self.send_response(404); self.end_headers()
    def _json(self,obj):
        b=json.dumps(obj).encode();self.send_response(200);self.send_header('Content-Type','application/json');self.send_header('Cache-Control','no-store');self.end_headers();self.wfile.write(b)
    def _html(self,text):
        b=text.encode();self.send_response(200);self.send_header('Content-Type','text/html; charset=utf-8');self.send_header('Cache-Control','no-store');self.end_headers();self.wfile.write(b)

def serve(host='0.0.0.0',port=None): ThreadingHTTPServer((host,port or settings.port),Handler).serve_forever()
